blocks.content:
1.contact {
2    padding: 80px;
3}
4
5.contact-form-container {
6    border-radius: 12px;
7    width: 100%;
8    max-width: 1180px;
9}
10
11.contact h2 {
12    margin-bottom: 32px;
13}
14
15.form-row {
16    display: flex;
17    justify-content: space-between;
18    gap: 20px;
19}
20
21.form-group {
22    margin-bottom: 30px;
23    flex: 1;
24}
25
26.form-group label {
27    font-size: 18px;
28    color: #25265e;
29    display: block;
30    margin-bottom: 5px;
31}
32
33.form-group input,
34.form-group select,
35.form-group textarea {
36    width: 100%;
37    height: 42px;
38    padding: 8px;
39    border-radius: 6px;
40    border: 1px solid #ccc;
41    font-size: 16px;
42    background-color: #ffffff;
43    color: #25265e;
44}
45
46.form-group textarea {
47    height: auto;
48}
49
50.form-group input::placeholder,
51.form-group textarea::placeholder {
52    color: #a0a0b0;
53}
54
55.form-group input:focus,
56.form-group select:focus,
57.form-group textarea:focus {
58    border-color: #c6b8f5;
59    outline: none;
60}
61
62.submit-btn {
63    display: block;
64    padding: 8px 30px;
65    background-color: #0556f3;
66    color: white;
67    font-size: 16px;
68    border: none;
69    border-radius: 6px;
70    margin-left: auto;
71}
72
73.submit-btn:hover {
74    background-color: #7e58cc;
75}
